1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the owner's {@code membershipLevel}, a numeric level from 1 to 3 fixed at
8	 * create time: it starts at 1, gains 1 when an email is present and 1 more when the
9	 * owner has no namesakes ({@code namesakeCount} of 0), capped at 3. Level 4 is reserved
10	 * for tenure and is never assigned here. Runs after the namesake count has been assigned,
11	 * so that value is available.
12	 */
13	public class AssignMembershipLevel {
14	
15	    static final int MAX_LEVEL = 3;
16	
17	    public void service(@Val Owner owner) {
18	        int level = 1;
19	        String email = owner.getEmail();
20	        if (email != null && !email.isBlank()) {
21	            level++;
22	        }
23	        Integer namesakeCount = owner.getNamesakeCount();
24	        if (namesakeCount != null && namesakeCount == 0) {
25	            level++;
26	        }
27	        owner.setMembershipLevel(Math.min(level, MAX_LEVEL));
28	    }
29	}
