2	
3	/**
4	 * The single definition of the Luhn check digit: a single digit (0-9) computed over the
5	 * digits contained in a string, with non-digit characters ignored. Used by the mapping
6	 * layer to derive an owner's {@code checkDigit} from its {@code customerCode}.
7	 *
8	 * <p>Lives beside {@link Owner} — the same home as {@link CityRegions} and
9	 * {@link OwnerIdentity} — so any layer can depend on it without a package cycle.
10	 */
11	public final class LuhnCheckDigit {
12	
13	    private LuhnCheckDigit() {
14	    }
15	
16	    /**
17	     * The Luhn check digit (0-9) over the digits in {@code value}, ignoring any non-digit
18	     * characters. {@code null} when {@code value} is {@code null}.
19	     */
20	    public static Integer of(String value) {
21	        if (value == null) {
22	            return null;
23	        }
24	        int sum = 0;
25	        boolean dbl = true;
26	        for (int i = value.length() - 1; i >= 0; i--) {
27	            char c = value.charAt(i);
28	            if (c < '0' || c > '9') {
29	                continue;
30	            }
31	            int d = c - '0';
32	            if (dbl) {
33	                d *= 2;
34	                if (d > 9) {
35	                    d -= 9;
36	                }
37	            }
38	            sum += d;
39	            dbl = !dbl;
40	        }
41	        return (10 - (sum % 10)) % 10;
42	    }
43	}
