1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	
5	/**
6	 * The single definition of the city-to-region fact (Sydney-&gt;NSW, Melbourne-&gt;VIC,
7	 * Brisbane-&gt;QLD). Both the mapping layer (which derives an owner's {@code locality}) and the
8	 * request-handling layer (which validates a postcode against the city's region) depend on this
9	 * one table, so adding a city updates both behaviours together.
10	 *
11	 * <p>Lives beside {@link Owner} — the same home as {@link OwnerIdentity} — so both layers can
12	 * depend on it without a package cycle.
13	 */
14	public final class CityRegions {
15	
16	    /** Region reported for a city that is not in the table. */
17	    public static final String UNKNOWN = "UNKNOWN";
18	
19	    /** City -&gt; canonical region; anything not listed has no known region. */
20	    private static final Map<String, String> CITY_REGION = Map.of(
21	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
22	
23	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	            "NSW", new int[] {2000, 2099},
26	            "VIC", new int[] {3000, 3099},
27	            "QLD", new int[] {4000, 4099});
28	
29	    private CityRegions() {
30	    }
31	
32	    /** The city's canonical region, or {@code null} when the city has no known region. */
33	    public static String regionOf(String city) {
34	        return CITY_REGION.get(city);
35	    }
36	
37	    /**
38	     * The region's inclusive 4-digit postcode range {@code {low, high}}, or {@code null} when the
39	     * region has no known range. The returned array is a fresh copy, so callers cannot mutate the
40	     * shared table.
41	     */
42	    public static int[] postcodeRange(String region) {
43	        int[] range = REGION_POSTCODES.get(region);
44	        return range == null ? null : range.clone();
45	    }
46	
47	    /**
48	     * The region whose postcode range contains {@code postcode}, or {@code null} when the
49	     * postcode is absent, not numeric, or in no known range.
50	     */
51	    public static String regionByPostcode(String postcode) {
52	        if (postcode == null || postcode.isEmpty()) {
53	            return null;
54	        }
55	        int value;
56	        try {
57	            value = Integer.parseInt(postcode);
58	        }
59	        catch (NumberFormatException ex) {
60	            return null;
61	        }
62	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
63	            int[] range = entry.getValue();
64	            if (value >= range[0] && value <= range[1]) {
65	                return entry.getKey();
66	            }
67	        }
68	        return null;
69	    }
70	
71	    /**
72	     * The owner's locality, preferring the postcode: the region whose range contains the
73	     * postcode wins, falling back to the city-to-region table when the postcode is absent or
74	     * in no known range, and finally {@link #UNKNOWN} when the city has no known region.
75	     */
76	    public static String localityOf(String city, String postcode) {
77	        String region = regionByPostcode(postcode);
78	        if (region != null) {
79	            return region;
80	        }
81	        return CITY_REGION.getOrDefault(city, UNKNOWN);
82	    }
83	}
