1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	/**
7	 * Single definition of how an owner telephone is converted to E.164 form: strip spaces,
8	 * dashes and brackets; keep a leading '+' and country code when present, otherwise assume
9	 * country code '+61' and drop a single leading '0' from the national digits; require 8 to
10	 * 15 digits after the '+', and additionally require the national-number length to match the
11	 * country code ('+61' => 9 national digits, '+1' => 10). Both {@code NormalizeOwnerTelephone}
12	 * (which normalizes the incoming request) and {@link OwnerIdentity} (which normalizes the
13	 * telephone component of the identityKey used for dedup) call this, so the create-time rule
14	 * and the dedup comparison can never silently diverge. Lives beside {@link Owner} so both the
15	 * mapping and request-handling layers can depend on it without a package cycle.
16	 */
17	public final class OwnerTelephones {
18	
19	    /**
20	     * Required national-number length per country calling code. Iterated in order so the
21	     * longest matching code wins when one code is a prefix of another; the current two
22	     * codes ('61', '1') are not prefixes of each other, so order is immaterial here.
23	     */
24	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_CODE = new LinkedHashMap<>();
25	    static {
26	        NATIONAL_LENGTH_BY_CODE.put("61", 9);
27	        NATIONAL_LENGTH_BY_CODE.put("1", 10);
28	    }
29	
30	    private OwnerTelephones() {
31	    }
32	
33	    /**
34	     * Converts {@code telephone} to its E.164 representation (e.g. "0412 345 678" ->
35	     * "+61412345678"), or returns {@code null} when it cannot form a valid E.164 number.
36	     */
37	    public static String toE164(String telephone) {
38	        if (telephone == null) {
39	            return null;
40	        }
41	        // Strip spaces, dashes and brackets; anything else must already be digits (or the
42	        // leading '+'), so a stray character makes the digit test below fail.
43	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
44	        String digits;
45	        if (cleaned.startsWith("+")) {
46	            // Explicit country code: keep it, just take the following digits.
47	            digits = cleaned.substring(1);
48	        } else {
49	            // No country code: assume '+61' and drop a single leading '0' from the national part.
50	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
51	            digits = "61" + national;
52	        }
53	        if (!digits.matches("\\d{8,15}")) {
54	            return null;
55	        }
56	        // Enforce the national-number length for known country codes ('+61' => 9, '+1' => 10);
57	        // any other code keeps only the generic 8-to-15-digit rule above.
58	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_CODE.entrySet()) {
59	            String code = entry.getKey();
60	            if (digits.startsWith(code)) {
61	                if (digits.length() - code.length() != entry.getValue()) {
62	                    return null;
63	                }
64	                break;
65	            }
66	        }
67	        return "+" + digits;
68	    }
69	}
