10	/**
11	 * Resolves the effective registration date and rolls it onto a business day. The effective
12	 * date is the request-supplied {@code registrationDate} when present, otherwise the
13	 * server's current date; when that date falls on a Saturday or Sunday it rolls forward to
14	 * the following Monday. The resolved business-day date is published so the steps that count
15	 * owners per day, stamp the owner and derive the membership number all use the same
16	 * adjusted value.
17	 */
18	public class ResolveRegistrationDate {
19	
20	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
21	        LocalDate effective = request.getRegistrationDate();
22	        if (effective == null) {
23	            effective = LocalDate.now();
24	        }
25	        registrationDate.set(toBusinessDay(effective));
26	    }
27	
28	    /** Rolls a weekend date forward to the following Monday; a business day is unchanged. */
29	    static LocalDate toBusinessDay(LocalDate date) {
30	        DayOfWeek day = date.getDayOfWeek();
31	        if (day == DayOfWeek.SATURDAY) {
32	            return date.plusDays(2);
33	        }
34	        if (day == DayOfWeek.SUNDAY) {
35	            return date.plusDays(1);
36	        }
37	        return date;
38	    }
39	}
