3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single definition of household membership, used by {@link AssignOwnerHousehold} (which
9	 * assigns the shared householdId), so the assignment rule lives in one place.
10	 * Two owners are in the same household when their lastName and address match. lastName is
11	 * compared case-insensitively with collapsed whitespace; address is compared using the
12	 * shared {@link AddressNormalizer} form, so the guard and the assignment agree with the
13	 * address that is stored and returned.
14	 */
15	final class OwnerHousehold {
16	
17	    private OwnerHousehold() {
18	    }
19	
20	    /** Whether an owner with the given lastName and address shares a household with {@code other}. */
21	    static boolean isSameHousehold(String lastName, String address, Owner other) {
22	        return normalize(lastName).equals(normalize(other.getLastName()))
23	                && AddressNormalizer.normalize(address).equals(AddressNormalizer.normalize(other.getAddress()));
24	    }
25	
26	    /** Lower-case and collapse whitespace runs to a single space for comparison. */
27	    private static String normalize(String value) {
28	        if (value == null) {
29	            return "";
30	        }
31	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
32	    }
33	}
