19	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
20	        String postcode = request.getPostcode();
21	        if (postcode == null || postcode.isEmpty()) {
22	            return; // optional: validated only when present
23	        }
24	        String region = CityRegions.regionOf(request.getCity());
25	        if (region == null) {
26	            return; // city has no known region -> any 4-digit postcode is accepted
27	        }
28	        int[] range = CityRegions.postcodeRange(region); // single shared source of the range fact
29	        int value = Integer.parseInt(postcode);
30	        if (value < range[0] || value > range[1]) {
31	            throw new InvalidPostcodeException(request.getCity(), postcode);
32	        }
33	    }
34	}
