3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * The single definition of address normalization, applied when an owner is created
8	 * (see {@link NormalizeOwnerAddress}) and reused by {@link OwnerHousehold} so that every
9	 * comparison of addresses uses the same normalized form as what is stored and returned.
10	 *
11	 * <p>Normalization trims and collapses whitespace runs to a single space, upper-cases the
12	 * value, and expands the common street-type abbreviations {@code ST->STREET},
13	 * {@code RD->ROAD} and {@code AVE->AVENUE} (matched as whole space-separated tokens).
14	 */
15	final class AddressNormalizer {
16	
17	    private static final Map<String, String> ABBREVIATIONS = Map.of(
18	            "ST", "STREET",
19	            "RD", "ROAD",
20	            "AVE", "AVENUE");
21	
22	    private AddressNormalizer() {
23	    }
24	
25	    /**
26	     * Normalize an address to its canonical stored/compared form. A {@code null} or
27	     * blank input yields the empty string.
28	     */
29	    static String normalize(String value) {
30	        if (value == null) {
31	            return "";
32	        }
33	        String collapsed = value.trim().replaceAll("\\s+", " ");
34	        if (collapsed.isEmpty()) {
35	            return "";
36	        }
37	        String[] tokens = collapsed.split(" ");
38	        StringBuilder result = new StringBuilder(collapsed.length());
39	        for (int i = 0; i < tokens.length; i++) {
40	            String token = tokens[i].toUpperCase(Locale.ROOT);
41	            token = ABBREVIATIONS.getOrDefault(token, token);
42	            if (i > 0) {
43	                result.append(' ');
44	            }
45	            result.append(token);
46	        }
47	        return result.toString();
48	    }
49	}
